# GENERATED by scripts/ops/wavegen.py from /home/rickybao/projects/dreamerv3/ops/waves/p2_w2_labels/spec.yaml -- do not edit by hand.

# Run ON an instance. Every check here corresponds to a failure
# that has actually cost work before.
set -uo pipefail
source /root/.dreamer_vast_env
fail=0
ok () { printf "  PASS %s\n" "$1"; }
bad () { printf "  FAIL %s\n" "$1"; fail=1; }

echo "== fork present (an empty $REPO fails as scattered ENOENT, never one message) =="
for f in scripts/env.sh scripts/ops/instance_helpers.sh probing/__init__.py; do
  [ -e "$REPO/$f" ] && ok "$f" || bad "MISSING $REPO/$f -- run push-repo"
done

echo "== interpreter =="
"${CONDA_ENV:-/venv/main}/bin/python" -c "import sys" 2>/dev/null \
  && ok "python in $CONDA_ENV" || bad "python broken in ${CONDA_ENV:-/venv/main}"

echo "== transfer tooling =="
for b in rsync tar; do
  p="$(command -v "$b" 2>/dev/null)"
  if [ -z "$p" ]; then bad "MISSING $b"
  elif [ ! -x "$p" ]; then bad "$b not executable ($p)"
  elif [ ! -s "$p" ]; then bad "$b is a 0-byte stub ($p) -- reinstall it"
  else ok "$b $(du -h "$p" | cut -f1)"; fi
done

echo "== disk =="
pct="$(df -P "$RUNROOT" | awk 'NR==2{gsub(/%/,"",$5); print $5}')"
[ "${pct:-100}" -lt 90 ] && ok "disk ${pct}% used" || bad "disk ${pct}% used"

echo "== producer reads every variable the wave sets =="
if [ ! -e "$REPO/scripts/tm2r3.sbatch" ]; then bad "MISSING producer scripts/tm2r3.sbatch"; else
  grep -qE '[$]\{?TDMPC2_CHECKOUT\b' "$REPO/scripts/tm2r3.sbatch" && ok "scripts/tm2r3.sbatch reads \$TDMPC2_CHECKOUT" || bad "STALE PRODUCER: scripts/tm2r3.sbatch never reads \$TDMPC2_CHECKOUT -- the wave sets it and it would bind NOTHING (run push-repo)"
  grep -qE '[$]\{?TM2R3_DOM\b' "$REPO/scripts/tm2r3.sbatch" && ok "scripts/tm2r3.sbatch reads \$TM2R3_DOM" || bad "STALE PRODUCER: scripts/tm2r3.sbatch never reads \$TM2R3_DOM -- the wave sets it and it would bind NOTHING (run push-repo)"
  grep -qE '[$]\{?TM2R3_DOSE\b' "$REPO/scripts/tm2r3.sbatch" && ok "scripts/tm2r3.sbatch reads \$TM2R3_DOSE" || bad "STALE PRODUCER: scripts/tm2r3.sbatch never reads \$TM2R3_DOSE -- the wave sets it and it would bind NOTHING (run push-repo)"
  grep -qE '[$]\{?TM2R3_ROOT\b' "$REPO/scripts/tm2r3.sbatch" && ok "scripts/tm2r3.sbatch reads \$TM2R3_ROOT" || bad "STALE PRODUCER: scripts/tm2r3.sbatch never reads \$TM2R3_ROOT -- the wave sets it and it would bind NOTHING (run push-repo)"
  grep -qE '[$]\{?TM2R3_SEED\b' "$REPO/scripts/tm2r3.sbatch" && ok "scripts/tm2r3.sbatch reads \$TM2R3_SEED" || bad "STALE PRODUCER: scripts/tm2r3.sbatch never reads \$TM2R3_SEED -- the wave sets it and it would bind NOTHING (run push-repo)"
  grep -qE '[$]\{?TM2R3_STAGE\b' "$REPO/scripts/tm2r3.sbatch" && ok "scripts/tm2r3.sbatch reads \$TM2R3_STAGE" || bad "STALE PRODUCER: scripts/tm2r3.sbatch never reads \$TM2R3_STAGE -- the wave sets it and it would bind NOTHING (run push-repo)"
  grep -qE '[$]\{?TM2_CONDA_ENV\b' "$REPO/scripts/tm2r3.sbatch" && ok "scripts/tm2r3.sbatch reads \$TM2_CONDA_ENV" || bad "STALE PRODUCER: scripts/tm2r3.sbatch never reads \$TM2_CONDA_ENV -- the wave sets it and it would bind NOTHING (run push-repo)"
  grep -qE '[$]\{?W2_SKIP_DUP_GATE\b' "$REPO/scripts/tm2r3.sbatch" && ok "scripts/tm2r3.sbatch reads \$W2_SKIP_DUP_GATE" || bad "STALE PRODUCER: scripts/tm2r3.sbatch never reads \$W2_SKIP_DUP_GATE -- the wave sets it and it would bind NOTHING (run push-repo)"
fi

echo "== repo generation stamp =="
want=2775e027
got="$(cat "$REPO/scripts/ops/VERSION" 2>/dev/null | head -1)"
case "$got" in
  "$want"*|*"${want%%-*}"*) ok "instance repo matches wave generation ($want)" ;;
  "") bad "no VERSION stamp on the instance -- run push-repo" ;;
  *) bad "REPO DRIFT: wave generated at $want, instance has $got -- run push-repo" ;;
esac

echo "== helpers =="
type dv3_queue_or_add >/dev/null 2>&1 && ok "helpers loaded ($(dv3_version))" \
  || bad "helpers not loaded -- run push-repo"

[ "$fail" -eq 0 ] && echo "PREFLIGHT PASS" || echo "PREFLIGHT FAIL"
exit "$fail"
